#[path="original_sha256.rs"]
mod original_sha256;
use serde_json::{json,Value};
use std::{collections::{BTreeMap,BTreeSet},fs,path::Path};
fn load(p:impl AsRef<Path>)->Value {serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn report(x:&mut Value){for phase in x["phases"].as_array_mut().unwrap(){assert!(phase.as_object_mut().unwrap().remove("wall").is_some());}let stats=x["stats"].as_array_mut().unwrap();assert!(stats.iter().filter(|v|v[0]=="wall_total").count()<=1);stats.retain(|v|v[0]!="wall_total");}
fn arms(x:&mut Value){for arm in ["original","candidate"] {report(&mut x[arm]);}}
fn canonical(mut rows:Vec<Value>)->Vec<String>{for row in &mut rows {let kind=row["kind"].as_str().unwrap().to_owned();let x=&mut row["data"];match kind.as_str(){"N4_NEW_JACOBIAN_IC_ATTEMPT"=>report(&mut x["report"]),"N4_COMPLETED_ATTEMPT"=>{for arm in ["baseline","candidate"]{report(&mut x[arm]);}},"N4_PUBLIC_ATTEMPT"=>report(&mut x["public"]),"N4_ORIGIN_ATTEMPT"|"N4_NORM_SAMPLER_ATTEMPT"=>arms(x),"N4_ORIGIN_SCOPE"=>{for a in x["all_attempts"].as_array_mut().unwrap(){arms(a);}},_=>()}}let mut out:Vec<_>=rows.iter().map(|v|serde_json::to_string(v).unwrap()).collect();out.sort();out}
fn records(log:&str)->Vec<Value>{let mut rows=vec![];for line in log.lines(){if let Some(i)=line.find("N4_"){if let Some((kind,body))=line[i..].split_once(' '){if kind.bytes().all(|c|c.is_ascii_uppercase()||c.is_ascii_digit()||c==b'_')&&body.starts_with('{')&&body.ends_with('}'){rows.push(json!({"kind":kind,"data":serde_json::from_str::<Value>(body).unwrap()}));}}}}rows}
fn main(){let args:Vec<_>=std::env::args().collect();assert_eq!(args.len(),4);let p=Path::new(&args[1]);let a=Path::new(&args[2]);let golden=load(&args[3]);let digests=load(a.join("canonical-digests73.json"));assert_eq!(digests.as_object().unwrap().len(),73);let jobs=load(p.join("all-jobs.json"));let mapping:BTreeMap<_,_>=[("completed-descent","completed"),("completed-v2-rho","V2"),("public-target","P1"),("two-primary","two-primary"),("bitangents","bitangents"),("kernels","kernels"),("gluing","gluing"),("chain-kernels","chain"),("odd-source","odd"),("odd-product","product"),("odd-refinement","refinement"),("new-target-ic","newIC"),("common-origin","origin"),("norm-sampling","sampling"),("beta-rational-lift","beta"),("beta-complete","complete")].into_iter().collect();let mut counts=BTreeMap::new();let mut verdicts=vec![];let mut skipped=0;let mut success=0;let mut pcc_gates=0;let mut distinct=BTreeSet::new();
for item in jobs.as_array().unwrap(){assert_eq!(item["run"]["status"],"completed");assert_eq!(item["run"]["conclusion"],"success");distinct.insert(item["run"]["workflow_id"].as_u64().unwrap());for job in item["api"]["structuredContent"]["jobs"].as_array().unwrap(){if job["name"]=="sign"{assert_eq!(job["conclusion"],"skipped");skipped+=1;continue;}let is_PCC=job["name"]=="gate";assert_eq!(job["conclusion"],"success");let id=job["id"].as_u64().unwrap();let name=job["name"].as_str().unwrap();let log=fs::read_to_string(p.join(format!("whole-job-{id}.txt"))).unwrap();assert!(log.contains("cc69f16d083cdce88813a7c3379e839e8454e063"));if is_PCC {let failures:Vec<_>=log.lines().filter_map(|line|line.split_once(' ').map(|x|x.1)).filter(|line|line.starts_with("PCC-")&&line.ends_with(": fail")).collect();assert!(failures.is_empty());for claim in["f4a048","423f66","8397ab"]{assert_eq!(log.matches(&format!("PCC-20261114-{claim}: not_covered")).count(),1);}pcc_gates+=1;}success+=1;if let Some(label)=mapping.get(name){let rows=records(&log);assert_eq!(canonical(rows.clone()),canonical(golden[*label].as_array().unwrap().clone()),"whole native JSON mismatch {label}");counts.insert(label.to_string(),rows.len());for line in log.lines(){if let Some(i)=line.find("{\"claim_id\":"){let v:Value=serde_json::from_str(&line[i..]).unwrap();assert_eq!(v["verdict"],"pass");assert!(v["reasons"].as_array().unwrap().is_empty());assert_eq!(v["commit"],"cc69f16d083cdce88813a7c3379e839e8454e063");let claim=v["claim_id"].as_str().unwrap();assert_eq!(v["claim_sha256"],digests[claim]);verdicts.push(v);}}}else if name=="arithmetic-audit"{let rows=records(&log);let sampler=rows.iter().filter(|v|v["kind"].as_str().unwrap().starts_with("N4_NORM_SAMPLER_")).cloned().collect::<Vec<_>>();assert_eq!(sampler.len(),86);assert_eq!(canonical(sampler),canonical(golden["sampling"].as_array().unwrap().clone()));let census=rows.iter().filter(|v|v["kind"]=="N4_ARITHMETIC_CENSUS").collect::<Vec<_>>();assert_eq!(census.len(),1);let expected=load(p.join("arithmetic-artifact-members/n4-arithmetic-output/expected-census.json"));assert_eq!(census[0]["data"],expected,"whole census and all metadata, NO masks");assert_eq!(expected["rows"].as_array().unwrap().len(),7113);assert!(log.contains("test result: ok. 1 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out;"));counts.insert("arithmetic-sampler".into(),86);}else {assert!(["gate","original-fixture","original-checkpoint"].contains(&name),"unexpected job {name}");}}}
assert_eq!(distinct.len(),20);assert_eq!(success,21);assert_eq!(skipped,2);assert_eq!(counts.values().sum::<usize>(),419);assert_eq!(verdicts.len(),75);let mut reuse=BTreeMap::<String,usize>::new();for v in &verdicts{*reuse.entry(v["claim_id"].as_str().unwrap().to_owned()).or_default()+=1;}assert_eq!(reuse.len(),73);let repeated:Vec<_>=reuse.iter().filter(|(_,n)|**n!=1).map(|(k,n)|(k.as_str(),*n)).collect();assert_eq!(repeated,vec![("PCC-20261113-01efbf",2),("PCC-20261113-671d42",2)]);
let arithmetic=p.join("arithmetic-artifact-members/n4-arithmetic-output");let names=["materialize","fetch-original","lock-solver","fetch-taps","lock-taps","frozen-registry","compile","native","ledger-unit","compare-build","all86","census-build","census","omitted-hook-canaries","derived-guards"];assert_eq!(fs::read_to_string(arithmetic.join("phases.txt")).unwrap(),names.iter().map(|x|format!("{x} 0\n")).collect::<String>());for n in names{assert_eq!(fs::read_to_string(arithmetic.join(format!("{n}.pipe-exits"))).unwrap(),"0 0\n");}for n in ["original","phase-caller","final-audit-source","final-original-785","final-derived"]{assert_eq!(fs::read_to_string(arithmetic.join(format!("{n}.exit"))).unwrap(),"0\n");}

let b=p.join("beta-artifact-members");
assert_eq!(fs::read_to_string(b.join("consumer-head.txt")).unwrap(),"cc69f16d083cdce88813a7c3379e839e8454e063\n");
assert_eq!(fs::read_to_string(b.join("producer-head.txt")).unwrap(),"3d49af7f3d0a28e76b79e4825c9d2324e85853d2\n");
let phases=[("fetch",0),("compile",0),("native",0),("bins",0),("compare",0),("identity-issue",0),("identity-replay",0),("identity-negative",101),("consumer-proof",0),("producer-proof",0),("binding-PCC-20261114-ea1776",0),("binding-PCC-20261114-59b526",0),("binding-PCC-20261114-1706b2",0),("binding-PCC-20261114-8ffe1f",0),("binding-PCC-20261114-42dab6",0),("binding-PCC-20261114-637454",0),("final-guards",0)];
assert_eq!(fs::read_to_string(b.join("phases.txt")).unwrap(),phases.iter().map(|(n,e)|format!("{n} {e} {e}\n")).collect::<String>());
for(n,e)in phases{assert_eq!(fs::read_to_string(b.join(format!("{n}.pipe-exits"))).unwrap(),format!("{e} 0\n"));}
for n in["original","phase-caller","final-source-guards"]{assert_eq!(fs::read_to_string(b.join(format!("{n}.exit"))).unwrap(),"0\n");}
assert!(fs::read_to_string(b.join("native.txt")).unwrap().contains("test result: ok. 2 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out;"));
for side in["consumer","producer"]{let log=fs::read_to_string(b.join(format!("{side}-proof.txt"))).unwrap();assert!(log.contains("20 thm   0 trusted")&&log.contains("1 thm   0 trusted"));}
let guards=fs::read_to_string(b.join("final-source-guards.txt")).unwrap();assert_eq!(guards.lines().count(),844);assert!(guards.lines().all(|s|s.ends_with(": OK")));
assert_eq!(fs::read(b.join("original-reference.sha256")).unwrap(),fs::read(a.join("beta-reference.sha256")).unwrap());
for name in["QuadraticRationalLift.lean","QuadraticNormIdentity.lean"]{assert_eq!(fs::read(b.join("producer-staged-source").join(name)).unwrap(),fs::read(a.join("beta-original-proof-source").join(name)).unwrap());}


assert_eq!(pcc_gates,2);
let c=p.join("complete-artifact-members");
assert_eq!(fs::read_to_string(c.join("consumer-head.txt")).unwrap(),"cc69f16d083cdce88813a7c3379e839e8454e063\n");
assert_eq!(fs::read_to_string(c.join("producer-head.txt")).unwrap(),"3d49af7f3d0a28e76b79e4825c9d2324e85853d2\n");
let cp=[("fetch",0),("compile",0),("native",0),("bins",0),("compare",0),("compare-negative",101),("identity-issue",0),("identity-replay",0),("identity-negative",101),("legacy-count-negative",101),("consumer-proof",0),("producer-proof",0),("binding-PCC-20261114-3237be",0),("binding-PCC-20261114-5098ee",0),("binding-PCC-20261114-15a9e4",0),("binding-PCC-20261114-a92216",0),("binding-PCC-20261114-07e7e3",0),("binding-PCC-20261114-9e1fdf",0),("binding-PCC-20261114-4036be",0),("final-guards",0)];
assert_eq!(fs::read_to_string(c.join("phases.txt")).unwrap(),cp.iter().map(|(n,e)|format!("{n} {e} {e}\n")).collect::<String>());
for(n,e)in cp {assert_eq!(fs::read_to_string(c.join(format!("{n}.pipe-exits"))).unwrap(),format!("{e} 0\n"));}
for n in["original","phase-caller","final-source-guards"]{assert_eq!(fs::read_to_string(c.join(format!("{n}.exit"))).unwrap(),"0\n");}
assert!(fs::read_to_string(c.join("native.txt")).unwrap().contains("test result: ok. 3 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out;"));
assert!(!c.join("omitted-record-must-not-accept.json").exists());
for side in["consumer","producer"]{let log=fs::read_to_string(c.join(format!("{side}-proof.txt"))).unwrap();assert!(log.contains("44 thm   0 trusted")&&log.contains("1 thm   0 trusted"));}
let guards=fs::read_to_string(c.join("final-source-guards.txt")).unwrap();assert_eq!(guards.lines().count(),881);assert!(guards.lines().all(|s|s.ends_with(": OK")));
assert_eq!(fs::read(c.join("original-reference.sha256")).unwrap(),fs::read(a.join("complete-reference.sha256")).unwrap());
for name in["CompleteRationalBeta.lean","CRTProjectionIdentity.lean"]{assert_eq!(fs::read(c.join("producer-staged-source").join(name)).unwrap(),fs::read(a.join("complete-original-proof-source").join(name)).unwrap());}
assert_eq!(load(c.join("all-native-records.json")),golden["complete"]);
let checkpoint=p.join("checkpoint-artifact-members");
for n in["original-gate","readback-meta","readback-pack","readback-resume"]{assert_eq!(fs::read_to_string(checkpoint.join(format!("{n}.exit"))).unwrap(),"0\n");}
assert_eq!(fs::read_to_string(checkpoint.join("source-head.txt")).unwrap(),"cc69f16d083cdce88813a7c3379e839e8454e063\n");
assert_eq!(load(checkpoint.join("remote-meta.json"))["head"],"cc69f16d083cdce88813a7c3379e839e8454e063");
let hex=|bytes:&[u8]| original_sha256::sha256(bytes).iter().map(|x|format!("{x:02x}")).collect::<String>();
let remote=fs::read_to_string(checkpoint.join("remote-inputs.sha256")).unwrap();assert_eq!(remote.lines().count(),3);
let mut names=BTreeSet::new();
for line in remote.lines(){let(h,path)=line.split_once("  ").unwrap();let name=Path::new(path).file_name().unwrap();assert_eq!(hex(&fs::read(checkpoint.join(name)).unwrap()),h);assert!(names.insert(name.to_str().unwrap()));}
assert_eq!(names,["remote-checkpoint.tar.gz","remote-RESUME.md","remote-meta.json"].into_iter().collect());
let original=fs::read_to_string(checkpoint.join("source-inputs.sha256")).unwrap();assert_eq!(original.lines().count(),4);
for line in original.lines(){let(h,path)=line.split_once("  ").unwrap();assert_eq!(hex(&fs::read(a.join("checkpoint-source-inputs").join(path)).unwrap()),h);}
assert_eq!(fs::read(checkpoint.join("pack-RESUME.md")).unwrap(),fs::read(checkpoint.join("remote-RESUME.md")).unwrap());
assert_eq!(fs::read(checkpoint.join("pack-meta.json")).unwrap(),fs::read(checkpoint.join("remote-meta.json")).unwrap());
let meta=load(checkpoint.join("remote-meta.json"));assert_eq!(meta["repo"],"cryptanalysis");assert_eq!(meta["branch"],"research/chained-transfer-public-target-20261113");
assert_eq!(fs::read(checkpoint.join("original-RESUME.md")).unwrap(),fs::read(checkpoint.join("remote-RESUME.md")).unwrap());
let out=json!({"source":"cc69f16d083cdce88813a7c3379e839e8454e063","distinct_workflows":20,"successful_runs":21,"failed_PCC_runs":0,"PCC_sign_jobs_skipped":2,"PCC_repair":"both automatic synchronize and body-edited gates success; f4a048/423f66/8397ab allnotcovered without failure; original b691 negative remains separate","whole_native_records":419,"per_workflow_native_counts":counts,"only_previously_frozen_wall_masks":true,"whole7113census_all_metadata_exact_no_masks":true,"arithmetic15_beta17_complete20_phase_pairs_exact":true,"complete_three_actual101_controls_alltee0":true,"complete3_unfiltered_all3wholeJSON_no_masks_both_original44plus1_gates7bindings":true,"all_final_guards_and_source_manifests_exact":true,"original_checkpoint_gate_readbacks0_exact_source_inputs_and_resume":true,"canonical_original_PCC_digests":73,"actual_pass_verdicts":75,"two_original_reused_claims_twice":["01efbf","671d42"],"scope":"unsigned data audit;20distinctworkflows/21automaticruns successful; no signed execution or performance standing"});
fs::write(a.join("audit-result.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();fs::write(a.join("all75-current-verdicts.json"),serde_json::to_vec(&verdicts).unwrap()).unwrap();println!("ALL419 native records exact under frozen old masks; whole7113census exact;73canonical/75passverdicts;20distinctworkflows21automaticSUCCESSruns/twoPCCsignskips;allphase/source/proof/checkpoint controls match. Unsigned.");}
